+        }
+    }
+
+    let recent_narrow = Rect::from_min_size(Pos2::ZERO, Vec2::new(220.0, super::super::shell::RIBBON_H));
+    let recent_rows = recent_drop::rows_of(&state, RecentKind::Project, near_right, recent_narrow, &pal);
+    for (_, r) in recent_rows {
